using System;
using System.Linq;
using Rhino.Geometry;

namespace BenchPlugin.Facade.Core
{
    /// <summary>
    /// One four-sided facade panel cut from a surface. Immutable.
    /// Corners are stored in order around the panel: c0 -> c1 -> c2 -> c3.
    /// Edge i runs from corner i to corner (i + 1) % 4.
    /// </summary>
    public sealed class Panel
    {
        private readonly Point3d[] _corners;

        public Panel(Point3d c0, Point3d c1, Point3d c2, Point3d c3, int index)
        {
            _corners = new[] { c0, c1, c2, c3 };
            Index = index;
            Area = ComputeArea(_corners);
            Deviation = ComputeDeviation(_corners);
        }

        /// <summary>Index of this panel in its source grid.</summary>
        public int Index { get; }

        /// <summary>Surface area of the panel, as the mean of its two triangulations.</summary>
        public double Area { get; }

        /// <summary>Distance from the fourth corner to the plane through the first three.</summary>
        public double Deviation { get; }

        /// <summary>A copy of the four corners, in order around the panel.</summary>
        public Point3d[] Corners => (Point3d[])_corners.Clone();

        public Point3d Corner(int i) => _corners[i];

        /// <summary>Average of the four corners.</summary>
        public Point3d Center => new Point3d(
            _corners.Average(p => p.X),
            _corners.Average(p => p.Y),
            _corners.Average(p => p.Z));

        /// <summary>Closed outline through the four corners.</summary>
        public Polyline OutlinePolyline =>
            new Polyline(new[] { _corners[0], _corners[1], _corners[2], _corners[3], _corners[0] });

        /// <summary>Closed outline curve through the four corners.</summary>
        public Curve Outline => new PolylineCurve(OutlinePolyline);

        /// <summary>Length of edge i (corner i to corner i + 1).</summary>
        public double EdgeLength(int i) => _corners[i].DistanceTo(_corners[(i + 1) % 4]);

        public double[] EdgeLengths => new[] { EdgeLength(0), EdgeLength(1), EdgeLength(2), EdgeLength(3) };

        /// <summary>Diagonal lengths: c0-c2 and c1-c3.</summary>
        public double[] DiagonalLengths => new[]
        {
            _corners[0].DistanceTo(_corners[2]),
            _corners[1].DistanceTo(_corners[3]),
        };

        /// <summary>Bounding rectangle width used for nesting and cut lists: mean of edges 0 and 2.</summary>
        public double FlatWidth => 0.5 * (EdgeLength(0) + EdgeLength(2));

        /// <summary>Bounding rectangle height used for nesting and cut lists: mean of edges 1 and 3.</summary>
        public double FlatHeight => 0.5 * (EdgeLength(1) + EdgeLength(3));

        public BoundingBox BoundingBox => new BoundingBox(_corners);

        public bool IsValid => _corners.All(p => p.IsValid);

        public Panel Transformed(Transform xform)
        {
            var c = Corners;
            for (int i = 0; i < 4; i++) c[i].Transform(xform);
            return new Panel(c[0], c[1], c[2], c[3], Index);
        }

        public override string ToString() =>
            $"Panel {Index} (area {Area:0.###}, deviation {Deviation:0.###})";

        private static double ComputeArea(Point3d[] c)
        {
            double TriArea(Point3d a, Point3d b, Point3d d) =>
                0.5 * Vector3d.CrossProduct(b - a, d - a).Length;

            double split02 = TriArea(c[0], c[1], c[2]) + TriArea(c[0], c[2], c[3]);
            double split13 = TriArea(c[1], c[2], c[3]) + TriArea(c[1], c[3], c[0]);
            return 0.5 * (split02 + split13);
        }

        private static double ComputeDeviation(Point3d[] c)
        {
            var normal = Vector3d.CrossProduct(c[1] - c[0], c[2] - c[0]);
            double len = normal.Length;
            if (len < 1e-12)
            {
                // First three corners are collinear: any plane through them may contain c3.
                return 0.0;
            }
            return Math.Abs((c[3] - c[0]) * normal) / len;
        }
    }
}

