using System.Collections.Generic;
using Grasshopper.Kernel;

namespace BenchPlugin.Facade.Core
{
    /// <summary>Shared tab/panel names and small helpers used by all Facade components.</summary>
    public static class FacadeInfo
    {
        public const string Category = "Facade";
        public const string SubParams = "Params";
        public const string SubPanels = "Panels";
        public const string SubAnalysis = "Analysis";
        public const string SubFabrication = "Fabrication";

        /// <summary>Unwraps panels, dropping nulls. Returns how many were dropped.</summary>
        public static List<Panel> Unwrap(IEnumerable<GH_Panel> goos, out int dropped)
        {
            var list = new List<Panel>();
            dropped = 0;
            foreach (var g in goos)
            {
                if (g?.Value != null) list.Add(g.Value);
                else dropped++;
            }
            return list;
        }

        /// <summary>Reads a panel list input, warning about null entries.</summary>
        public static List<Panel> GetPanels(GH_Component owner, IGH_DataAccess da, int index)
        {
            var goos = new List<GH_Panel>();
            da.GetDataList(index, goos);
            var panels = Unwrap(goos, out int dropped);
            if (dropped > 0)
                owner.AddRuntimeMessage(GH_RuntimeMessageLevel.Remark, $"{dropped} null panel(s) ignored.");
            return panels;
        }
    }
}

