using System;
using System.Collections.Generic;
using System.Linq;
using BenchPlugin.Facade.Core;

namespace BenchPlugin.Facade.Analysis
{
    public static class PanelClassifier
    {
        public const string Flat = "flat";
        public const string ColdBent = "cold-bent";
        public const string Custom = "custom";

        /// <summary>Factor on Tolerance up to which a panel can still be cold-bent.</summary>
        public const double ColdBentFactor = 10.0;

        public static bool IsFlat(Panel panel, double tolerance) => panel.Deviation <= tolerance;

        public static string Classify(Panel panel, double tolerance)
        {
            if (panel.Deviation <= tolerance) return Flat;
            if (panel.Deviation <= ColdBentFactor * tolerance) return ColdBent;
            return Custom;
        }
    }

    public static class PanelGrouping
    {
        /// <summary>
        /// Assigns a group number per panel (0-based, in order of first appearance).
        /// Two panels match when their sorted edge lengths and sorted diagonal lengths
        /// each differ by at most <paramref name="tolerance"/>.
        /// </summary>
        public static int[] Group(IReadOnlyList<Panel> panels, double tolerance, out List<int> representatives)
        {
            var signatures = panels.Select(Signature).ToArray();
            var groups = new int[panels.Count];
            representatives = new List<int>();

            for (int i = 0; i < panels.Count; i++)
            {
                int found = -1;
                for (int g = 0; g < representatives.Count; g++)
                {
                    if (Matches(signatures[i], signatures[representatives[g]], tolerance))
                    {
                        found = g;
                        break;
                    }
                }
                if (found < 0)
                {
                    found = representatives.Count;
                    representatives.Add(i);
                }
                groups[i] = found;
            }
            return groups;
        }

        /// <summary>Sorted edges (4 values) followed by sorted diagonals (2 values).</summary>
        private static double[] Signature(Panel p)
        {
            var edges = p.EdgeLengths;
            var diags = p.DiagonalLengths;
            Array.Sort(edges);
            Array.Sort(diags);
            return edges.Concat(diags).ToArray();
        }

        private static bool Matches(double[] a, double[] b, double tolerance)
        {
            for (int i = 0; i < a.Length; i++)
                if (Math.Abs(a[i] - b[i]) > tolerance) return false;
            return true;
        }
    }
}

