using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

namespace BenchPlugin.Facade.Fabrication
{
    /// <summary>A rectangle to nest. Plain data, so nesting can run off the UI thread.</summary>
    public readonly struct NestPart
    {
        public NestPart(int id, double width, double height)
        {
            Id = id;
            Width = width;
            Height = height;
        }

        public int Id { get; }
        public double Width { get; }
        public double Height { get; }
    }

    /// <summary>Where a part ended up. X/Y are the lower-left corner in sheet-local coordinates.</summary>
    public readonly struct NestPlacement
    {
        public NestPlacement(int id, int sheet, double x, double y, double width, double height, bool rotated)
        {
            Id = id;
            Sheet = sheet;
            X = x;
            Y = y;
            Width = width;
            Height = height;
            Rotated = rotated;
        }

        public int Id { get; }
        public int Sheet { get; }
        public double X { get; }
        public double Y { get; }
        /// <summary>Placed width (after rotation).</summary>
        public double Width { get; }
        /// <summary>Placed height (after rotation).</summary>
        public double Height { get; }
        public bool Rotated { get; }
    }

    public sealed class NestResult
    {
        /// <summary>Placements, indexed like the input parts; null entries did not fit.</summary>
        public NestPlacement?[] Placements { get; set; }
        public int SheetCount { get; set; }
        public int UnplacedCount { get; set; }
        public double PlacedArea { get; set; }
        public double SheetWidth { get; set; }
        public double SheetHeight { get; set; }

        public double Utilization =>
            SheetCount == 0 ? 0.0 : PlacedArea / (SheetCount * SheetWidth * SheetHeight);
    }

    /// <summary>
    /// Shelf nesting: parts sorted tallest first, filled left to right along shelves;
    /// a new shelf opens above when a part does not fit, a new sheet when a shelf does not fit.
    /// A part is turned 90 degrees only when it fits turned but not as-is.
    /// </summary>
    public static class ShelfNester
    {
        public static NestResult Nest(
            IReadOnlyList<NestPart> parts,
            double sheetWidth,
            double sheetHeight,
            double spacing,
            CancellationToken cancel,
            Action<double> progress = null)
        {
            var result = new NestResult
            {
                Placements = new NestPlacement?[parts.Count],
                SheetWidth = sheetWidth,
                SheetHeight = sheetHeight,
            };

            // Usable area inside the edge margin.
            double usableW = sheetWidth - 2 * spacing;
            double usableH = sheetHeight - 2 * spacing;

            var order = Enumerable.Range(0, parts.Count)
                .OrderByDescending(i => parts[i].Height)
                .ThenBy(i => i)
                .ToArray();

            int sheet = -1;       // no sheet opened yet
            double shelfY = 0;    // bottom of current shelf (usable-area coordinates)
            double shelfH = 0;    // height of current shelf
            double cursorX = 0;   // next free x on current shelf

            int reportEvery = Math.Max(1, parts.Count / 100);

            bool FitsHere(double w, double h) =>
                sheet >= 0 && cursorX + w <= usableW && shelfY + h <= usableH;

            for (int k = 0; k < order.Length; k++)
            {
                cancel.ThrowIfCancellationRequested();
                if (progress != null && k % reportEvery == 0) progress((double)k / order.Length);

                int idx = order[k];
                var part = parts[idx];
                double w = part.Width, h = part.Height;

                bool fitsUpright = w <= usableW && h <= usableH;
                bool fitsTurned = h <= usableW && w <= usableH;
                if (!(w > 0 && h > 0) || (!fitsUpright && !fitsTurned))
                {
                    result.UnplacedCount++;
                    continue;
                }

                bool rotated;
                if (!TryOrient(FitsHere, w, h, out rotated))
                {
                    // New shelf above the current one.
                    if (sheet >= 0)
                    {
                        shelfY += shelfH + (shelfH > 0 ? spacing : 0);
                        shelfH = 0;
                        cursorX = 0;
                    }
                    if (!TryOrient(FitsHere, w, h, out rotated))
                    {
                        // New sheet.
                        sheet++;
                        shelfY = 0;
                        shelfH = 0;
                        cursorX = 0;
                        if (!TryOrient(FitsHere, w, h, out rotated))
                        {
                            // Cannot happen given the fit checks above, but stay safe.
                            result.UnplacedCount++;
                            continue;
                        }
                    }
                }

                double pw = rotated ? h : w;
                double ph = rotated ? w : h;
                result.Placements[idx] = new NestPlacement(
                    part.Id, sheet, spacing + cursorX, spacing + shelfY, pw, ph, rotated);
                result.PlacedArea += pw * ph;

                cursorX += pw + spacing;
                shelfH = Math.Max(shelfH, ph);
            }

            result.SheetCount = sheet + 1;
            progress?.Invoke(1.0);
            return result;
        }

        private static bool TryOrient(Func<double, double, bool> fits, double w, double h, out bool rotated)
        {
            rotated = false;
            if (fits(w, h)) return true;
            if (fits(h, w))
            {
                rotated = true;
                return true;
            }
            return false;
        }
    }
}

