                sb.Append(p.Index.ToString(ci)).Append(',')
                  .Append(p.FlatWidth.ToString("0.###", ci)).Append(',')
                  .Append(p.FlatHeight.ToString("0.###", ci)).Append(',')
                  .Append(p.Area.ToString("0.###", ci)).Append(',')
                  .Append(p.Deviation.ToString("0.####", ci)).Append('\n');
            }
            return sb.ToString();
        }
    }
}

