using System;
using System.Collections.Generic;
using BenchPlugin.Facade.Core;
using Grasshopper.Kernel;
using Rhino.Geometry;

namespace BenchPlugin.Facade.Components
{
    public class PanelizeSurfaceComponent : GH_Component
    {
        public PanelizeSurfaceComponent()
            : base("Panelize Surface", "Panelize",
                "Divides a surface's domain evenly into a grid of four-sided panels",
                FacadeInfo.Category, FacadeInfo.SubPanels)
        {
        }

        public override Guid ComponentGuid => new Guid("c41f8e27-90ab-4d3e-b6a5-2e7d1f0c9a31");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddSurfaceParameter("Surface", "S", "Surface to panelize", GH_ParamAccess.item);
            pManager.AddIntegerParameter("U Count", "U", "Number of panels in the U direction", GH_ParamAccess.item, 10);
            pManager.AddIntegerParameter("V Count", "V", "Number of panels in the V direction", GH_ParamAccess.item, 6);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddParameter(new Param_Panel(), "Panels", "P", "Panels, indexed row by row (index = v * U Count + u)", GH_ParamAccess.list);
            pManager.AddCurveParameter("Outlines", "O", "Closed panel outlines", GH_ParamAccess.list);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            Surface surface = null;
            int uCount = 0, vCount = 0;
            if (!DA.GetData(0, ref surface) || surface == null) return;
            if (!DA.GetData(1, ref uCount)) return;
            if (!DA.GetData(2, ref vCount)) return;

            if (uCount < 1 || vCount < 1)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "U Count and V Count must be at least 1.");
                return;
            }

            Interval du = surface.Domain(0);
            Interval dv = surface.Domain(1);

            // Evaluate each grid point once; neighbouring panels share corners.
            var grid = new Point3d[uCount + 1, vCount + 1];
            for (int i = 0; i <= uCount; i++)
            {
                double u = du.ParameterAt((double)i / uCount);
                for (int j = 0; j <= vCount; j++)
                    grid[i, j] = surface.PointAt(u, dv.ParameterAt((double)j / vCount));
            }

            var panels = new List<GH_Panel>(uCount * vCount);
            var outlines = new List<Curve>(uCount * vCount);
            for (int j = 0; j < vCount; j++)
            {
                for (int i = 0; i < uCount; i++)
                {
                    var panel = new Panel(grid[i, j], grid[i + 1, j], grid[i + 1, j + 1], grid[i, j + 1], j * uCount + i);
                    panels.Add(new GH_Panel(panel));
                    outlines.Add(panel.Outline);
                }
            }

            DA.SetDataList(0, panels);
            DA.SetDataList(1, outlines);
        }
    }
}

