using Grasshopper.Kernel;

namespace BenchPlugin.Facade.Components
{
    public class GroupIdenticalPanelsComponent : GH_Component
    {
        public GroupIdenticalPanelsComponent()
            : base("Group Identical Panels", "Group",
                "Groups panels whose sorted edge lengths and sorted diagonal lengths match within tolerance",
                FacadeInfo.Category, FacadeInfo.SubFabrication)
        {
        }

        public override Guid ComponentGuid => new Guid("a07d3e95-6b18-4c2f-9d54-3f2e8b1c6a40");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new Param_Panel(), "Panels", "P", "Panels to group", GH_ParamAccess.list);
            pManager.AddNumberParameter("Tolerance", "T", "Maximum length difference for panels to count as identical", GH_ParamAccess.item, 1.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddIntegerParameter("Group", "G", "Group number per panel, from 0 in order of first appearance", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Group Count", "N", "Number of groups", GH_ParamAccess.item);
            pManager.AddParameter(new Param_Panel(), "Representatives", "R", "First panel of each group", GH_ParamAccess.list);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = FacadeInfo.GetPanels(this, DA, 0);
            double tolerance = 1.0;
            if (!DA.GetData(1, ref tolerance)) return;

            if (tolerance < 0)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Tolerance must not be negative.");
                return;
            }

            var groups = PanelGrouping.Group(panels, tolerance, out var reps);

            DA.SetDataList(0, groups);
            DA.SetData(1, reps.Count);
            DA.SetDataList(2, reps.Select(i => new GH_Panel(panels[i])));
        }
    }
}

