using System;
using System.IO;
using BenchPlugin.Facade.Core;
using BenchPlugin.Facade.Fabrication;
using Grasshopper.Kernel;

namespace BenchPlugin.Facade.Components
{
    public class CutListComponent : GH_Component
    {
        public CutListComponent()
            : base("Cut List", "CutList",
                "Builds a CSV cut list (index, width, height, area, deviation) and optionally writes it to disk",
                FacadeInfo.Category, FacadeInfo.SubFabrication)
        {
        }

        public override Guid ComponentGuid => new Guid("e6b45a0c-1f73-4d8e-a2c9-07b3d5f81e62");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new Param_Panel(), "Panels", "P", "Panels to list", GH_ParamAccess.list);
            pManager.AddTextParameter("Path", "F", "File to write the CSV to", GH_ParamAccess.item, string.Empty);
            pManager.AddBooleanParameter("Write", "W", "Write the CSV to Path", GH_ParamAccess.item, false);
            pManager[1].Optional = true;
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddTextParameter("CSV", "CSV", "Cut list as CSV text", GH_ParamAccess.item);
            pManager.AddBooleanParameter("Written", "OK", "True when the file was written", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = FacadeInfo.GetPanels(this, DA, 0);
            string path = string.Empty;
            bool write = false;
            DA.GetData(1, ref path);
            DA.GetData(2, ref write);

            string csv = CutListWriter.ToCsv(panels);
            DA.SetData(0, csv);

            bool written = false;
            if (write)
            {
                if (string.IsNullOrWhiteSpace(path))
                {
                    AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Write is true but Path is empty.");
                }
                else
                {
                    try
                    {
                        File.WriteAllText(path, csv);
                        written = true;
                    }
                    catch (Exception ex)
                    {
                        AddRuntimeMessage(GH_RuntimeMessageLevel.Error, $"Could not write '{path}': {ex.Message}");
                    }
                }
            }
            DA.SetData(1, written);
        }
    }
}

