using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using BenchPlugin.Facade.Core;
using BenchPlugin.Facade.Fabrication;
using Grasshopper.Kernel;
using Rhino.Geometry;

namespace BenchPlugin.Facade.Components
{
    /// <summary>
    /// Shelf-nests panel rectangles onto sheets on a background thread.
    ///
    /// Each solution runs in one of two phases:
    ///  * Compute: inputs changed. Any running job is cancelled, a new job per iteration is
    ///    started on the thread pool and the component outputs nothing for now.
    ///  * Deliver: all jobs finished. The component schedules a fresh solution of itself and
    ///    publishes the stored results without recomputing.
    /// A generation counter makes sure results of a superseded run are never delivered.
    /// </summary>
    public class NestOnSheetsComponent : GH_Component
    {
        private const double SheetGap = 100.0;

        private sealed class Job
        {
            public Task<NestResult> Task;
            public List<int> PanelIndices;   // panel index per part, in input order
            public double SheetWidth;
            public double SheetHeight;
        }

        private CancellationTokenSource _cts;
        private Dictionary<int, Job> _jobs = new Dictionary<int, Job>();
        private int _generation;
        private bool _delivering;

        public NestOnSheetsComponent()
            : base("Nest On Sheets", "Nest",
                "Shelf-nests panel rectangles onto sheets. Runs in the background.",
                FacadeInfo.Category, FacadeInfo.SubFabrication)
        {
        }

        public override Guid ComponentGuid => new Guid("57c2d8a1-e90f-4b36-8a7d-c14f6e2b9d03");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new Param_Panel(), "Panels", "P", "Panels to nest", GH_ParamAccess.list);
            pManager.AddNumberParameter("Sheet Width", "W", "Sheet width", GH_ParamAccess.item, 3000.0);
            pManager.AddNumberParameter("Sheet Height", "H", "Sheet height", GH_ParamAccess.item, 1500.0);
            pManager.AddNumberParameter("Spacing", "S", "Gap between parts and from the sheet edge", GH_ParamAccess.item, 10.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
