                parts.Add(new NestPart(i, panels[i].FlatWidth, panels[i].FlatHeight));

            var token = _cts.Token;
            int generation = _generation;
            var job = new Job
            {
                PanelIndices = panels.Select(p => p.Index).ToList(),
                SheetWidth = sheetW,
                SheetHeight = sheetH,
            };
            job.Task = Task.Run(
                () => ShelfNester.Nest(parts, sheetW, sheetH, spacing, token, f => ReportProgress(generation, f)),
                token);
            _jobs[DA.Iteration] = job;
        }

        protected override void AfterSolveInstance()
        {
            if (_delivering)
            {
                _delivering = false;
                return;
            }
            if (_jobs.Count == 0) return;

            Message = "Nesting...";
            int generation = _generation;
            var tasks = _jobs.Values.Select(j => (Task)j.Task).ToArray();

            Task.WhenAll(tasks).ContinueWith(_ =>
            {
                Rhino.RhinoApp.InvokeOnUiThread((Action)(() => ScheduleDelivery(generation)));
            }, TaskScheduler.Default);
        }

        private void ScheduleDelivery(int generation)
        {
            if (generation != _generation) return;   // superseded
            if (_jobs.Values.All(j => j.Task.IsCanceled)) return;

            var doc = OnPingDocument();
            if (doc == null) return;

            doc.ScheduleSolution(1, d =>
            {
                if (generation != _generation) return;
                _delivering = true;
                ExpireSolution(false);
            });
        }

        private void Deliver(IGH_DataAccess DA)
        {
            if (!_jobs.TryGetValue(DA.Iteration, out var job)) return;
            var task = job.Task;

            if (task.IsFaulted)
            {
                var ex = task.Exception?.GetBaseException();
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Nesting failed: " + (ex?.Message ?? "unknown error"));
                Message = "Failed";
                return;
            }
            if (task.IsCanceled || !task.IsCompleted) return;

            var result = task.Result;
            var outlines = new List<Curve>();
            var sheets = new List<int>();
            foreach (var placement in result.Placements)
            {
                if (placement == null) continue;
                var pl = placement.Value;
                double ox = pl.Sheet * (job.SheetWidth + SheetGap);
                var rect = new Rectangle3d(Plane.WorldXY,
                    new Point3d(ox + pl.X, pl.Y, 0),
                    new Point3d(ox + pl.X + pl.Width, pl.Y + pl.Height, 0));
                outlines.Add(rect.ToNurbsCurve());
                sheets.Add(pl.Sheet);
            }

            if (result.UnplacedCount > 0)
                AddRuntimeMessage(GH_RuntimeMessageLevel.Warning,
                    $"{result.UnplacedCount} panel(s) fit on no sheet and were left out.");

            DA.SetDataList(0, outlines);
            DA.SetDataList(1, sheets);
            DA.SetData(2, result.SheetCount);
            DA.SetData(3, result.Utilization);

            Message = $"{result.SheetCount} sheet(s)";
        }

        private int _lastPercent = -1;

        private void ReportProgress(int generation, double fraction)
        {
            int percent = (int)(fraction * 100);
            if (percent == Interlocked.Exchange(ref _lastPercent, percent)) return;

            Rhino.RhinoApp.InvokeOnUiThread((Action)(() =>
            {
                if (generation != _generation || _delivering) return;
                Message = $"Nesting {percent}%";
                OnDisplayExpired(false);
            }));
        }

        private void CancelRunning()
        {
            if (_cts == null) return;
            _cts.Cancel();
            _cts.Dispose();
            _cts = null;
        }

        public override void RemovedFromDocument(GH_Document document)
        {
            _generation++;
            CancelRunning();
            base.RemovedFromDocument(document);
        }

        public override void DocumentContextChanged(GH_Document document, GH_DocumentContext context)
        {
            if (context == GH_DocumentContext.Close || context == GH_DocumentContext.Unloaded)
            {
                _generation++;
                CancelRunning();
            }
            base.DocumentContextChanged(document, context);
        }
    }
}
